using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具管理器 — 管理玩家当前持有的所有道具。
/// 挂载在 Player GameObject 上，通过 PlayerManager 的持久化机制自动跟随跨场景。
///
/// 核心职责:
///   1. 管理道具集合（添加/移除/查询/丢弃/转移）
///   2. 执行道具效果（OnAcquire / OnRemove）
///   3. 通知事件（供 UI Controller 监听）
/// </summary>
public class ItemManager : MonoBehaviour
{
    [Header("丢弃配置")]
    [SerializeField] private GameObject _itemDropPrefab; // 丢弃道具时生成的拾取物预制体

    [Header("调试")]
    [SerializeField] private List<ItemData> _initialItems; // Inspector 调试用

    private readonly List<ItemData> _items = new List<ItemData>();
    private readonly Dictionary<string, ItemData> _itemDict = new Dictionary<string, ItemData>();
    private readonly Dictionary<string, int> _itemCounts = new Dictionary<string, int>();

    /// <summary>当前道具列表（只读），每种道具只出现一次</summary>
    public IReadOnlyList<ItemData> Items => _items;

    /// <summary>道具种类数量</summary>
    public int Count => _items.Count;

    // ========== 事件 ==========

    /// <summary>道具获得: (itemData)</summary>
    public event Action<ItemData> OnItemAcquired;

    /// <summary>道具移除: (itemData)</summary>
    public event Action<ItemData> OnItemRemoved;

    /// <summary>道具丢弃: (itemData, worldPosition)</summary>
    public event Action<ItemData, Vector3> OnItemDropped;

    /// <summary>道具转移: 从 (fromOwner, itemData) 转移到 (toOwner, itemData)</summary>
    public static event Action<ItemManager, ItemManager, ItemData> OnItemTransferred;

    // ========== Unity 生命周期 ==========

    private void Start()
    {
        // Inspector 调试：自动获得初始道具
        foreach (var item in _initialItems)
        {
            if (item != null)
                AcquireItem(item);
        }
    }

    // ========== 核心方法 ==========

    /// <summary>
    /// 获得道具 — 每次获取都执行效果（支持叠加）。
    /// maxCount=0 表示无上限。
    /// </summary>
    public bool AcquireItem(ItemData item)
    {
        if (item == null) return false;

        int max = item.maxCount;
        bool hasItem = _itemDict.ContainsKey(item.itemId);
        int currentCount = hasItem ? _itemCounts[item.itemId] : 0;

        // 达到上限
        if (max > 0 && currentCount >= max)
            return false;

        // 每次获取都执行效果
        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = currentCount + 1;
        }

        OnItemAcquired?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 移除道具 — 每次移除都执行清理（支持叠加效果逐层移除）。
    /// 数量归零时从集合移除。
    /// </summary>
    public bool RemoveItem(string itemId)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次移除都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具 — 在世界坐标生成可拾取的掉落物。
    /// 与 RemoveItem 的区别：丢弃会在场景中生成 ItemPickup GameObject。
    /// </summary>
    public bool DropItem(string itemId, Vector3 worldPosition)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次丢弃都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 在世界坐标生成掉落物
        SpawnItemPickup(item, worldPosition);

        OnItemDropped?.Invoke(item, worldPosition);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具在玩家脚下
    /// </summary>
    public bool DropItemAtPlayer(string itemId)
    {
        return DropItem(itemId, transform.position + (Vector3)(UnityEngine.Random.insideUnitCircle * 0.5f));
    }

    /// <summary>
    /// 将道具转移给另一个拥有者。
    /// 从当前所有者的集合移除，添加到目标所有者的集合。
    /// 用于交易 / 队友共享道具等场景。
    /// </summary>
    public bool TransferItem(string itemId, ItemManager targetOwner)
    {
        if (targetOwner == null || !_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 目标不能已有同 ID 道具且已达上限
        if (targetOwner.HasItem(itemId))
        {
            int targetMax = item.maxCount;
            int targetCount = targetOwner.GetItemCount(itemId);
            if (targetMax > 0 && targetCount >= targetMax)
                return false;
        }

        // 从当前所有者移除一份
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            item.effect?.OnRemove(gameObject);
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 添加到目标
        targetOwner.AcquireItemInternal(item);

        OnItemTransferred?.Invoke(this, targetOwner, item);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>内部获得道具（供 TransferItem 使用）</summary>
    private void AcquireItemInternal(ItemData item)
    {
        bool hasItem = _itemDict.ContainsKey(item.itemId);

        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = _itemCounts[item.itemId] + 1;
        }

        OnItemAcquired?.Invoke(item);
    }

    /// <summary>是否有指定道具</summary>
    public bool HasItem(string itemId) => _itemDict.ContainsKey(itemId);

    /// <summary>获取道具</summary>
    public ItemData GetItem(string itemId)
        => _itemDict.TryGetValue(itemId, out var item) ? item : null;

    /// <summary>获取道具持有数量（不存在返回0）</summary>
    public int GetItemCount(string itemId)
        => _itemCounts.TryGetValue(itemId, out var count) ? count : 0;

    // ========== 私有方法 ==========

    /// <summary>在指定世界位置生成可拾取的道具掉落物</summary>
    private void SpawnItemPickup(ItemData item, Vector3 position)
    {
        GameObject prefab = _itemDropPrefab;
        if (prefab == null)
        {
            // 如果没有配置掉落预制体，创建一个默认的
            prefab = CreateDefaultPickup();
        }

        GameObject go = Instantiate(prefab, position, Quaternion.identity);
        go.name = $"ItemPickup_{item.itemId}";

        var pickup = go.GetComponent<ItemPickup>();
        if (pickup == null)
            pickup = go.AddComponent<ItemPickup>();
        pickup.itemData = item;
    }

    /// <summary>创建默认拾取物预制体（运行时兜底）</summary>
    private GameObject CreateDefaultPickup()
    {
        var go = new GameObject("DefaultItemPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(ItemPickup));
        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = null; // 使用默认图标
        sr.drawMode = SpriteDrawMode.Simple;
        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.5f;
        return go;
    }
}

using UnityEngine;

/// <summary>
/// 道具拾取物 — 场景中可拾取的道具 GameObject。
///
/// 交互方式 (近距离按键):
///   1. 玩家靠近时高亮显示 + 弹出详情 UI
///   2. 按 F 键拾取
///   3. 不再通过碰撞自动拾取
/// </summary>
public class ItemPickup : MonoBehaviour
{
    [Header("道具数据")]
    public ItemData itemData;

    [Header("交互距离")]
    [Tooltip("玩家可交互的最大距离")]
    public float pickupRadius = 1.5f;

    [Header("表现")]
    public GameObject pickupEffectPrefab;

    [Header("漂浮动画")]
    [SerializeField] private bool _enableFloatAnimation = true;
    [SerializeField] private float _floatAmplitude = 0.15f;
    [SerializeField] private float _floatFrequency = 2f;
    [SerializeField] private float _rotationSpeed = 30f;

    [Header("高亮")]
    [SerializeField] private float _highlightScale = 1.3f;
    [SerializeField] private Color _highlightTint = new Color(1f, 1f, 0.7f, 1f);

    /// <summary>当前是否在玩家交互范围内</summary>
    public bool IsInRange { get; private set; }

    /// <summary>是否为商店商品（靠近时走购买流程而非拾取）</summary>
    public bool IsShopItem { get; set; }

    /// <summary>商店价格（从 ItemData.price 读取）</summary>
    public int ShopPrice => itemData != null ? itemData.price : 10;

    private Vector3 _startPosition;
    private SpriteRenderer _spriteRenderer;
    private Color _baseColor;
    private Vector3 _baseScale;

    private void Awake()
    {
        _spriteRenderer = GetComponent<SpriteRenderer>();
        _startPosition = transform.position;
        _baseScale = transform.localScale;

        if (_spriteRenderer != null)
        {
            _baseColor = _spriteRenderer.color;

            if (itemData != null && itemData.icon != null)
                _spriteRenderer.sprite = itemData.icon;
        }
    }

    private void Update()
    {
        if (!_enableFloatAnimation) return;

        float t = Time.time * _floatFrequency;
        Vector3 floatOffset = Vector3.up * (Mathf.Sin(t) * _floatAmplitude);

        if (IsInRange)
        {
            transform.localScale = _baseScale * _highlightScale;
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_baseColor, _highlightTint, 0.5f);
        }
        else
        {
            transform.localScale = Vector3.Lerp(transform.localScale, _baseScale, Time.deltaTime * 8f);
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_spriteRenderer.color, _baseColor, Time.deltaTime * 8f);
        }

        transform.position = _startPosition + floatOffset;
        transform.Rotate(Vector3.forward, _rotationSpeed * Time.deltaTime);
    }

    /// <summary>由 ItemInteractionHandler 调用，标记在范围内</summary>
    public void SetInRange(bool inRange)
    {
        IsInRange = inRange;
    }

    /// <summary>执行拾取 — 返回道具数据</summary>
    public ItemData Pickup()
    {
        if (pickupEffectPrefab != null)
            Instantiate(pickupEffectPrefab, transform.position, Quaternion.identity);

        return itemData;
    }

    /// <summary>品质 → 颜色映射</summary>
    public static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),
        _                     => Color.white
    };
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [Tooltip("每分钟射击次数，300 = 每秒5发")]
    [SerializeField] private float shotsPerMinute = 300f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    [Header("进化倾向")]
    [Tooltip("进化倾向：正值=朝向宿主，负值=朝向独特。范围 -100 ~ 100")]
    [SerializeField] private float evolutionTendency = 0f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => 60f / shotsPerMinute;
    public float ShotsPerMinute => shotsPerMinute;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    /// <summary>进化倾向：正值=朝向宿主（金色），负值=朝向独特（紫色）。范围 -100 ~ 100</summary>
    public float EvolutionTendency => evolutionTendency;

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        // 无敌帧：免疫期间不受到任何伤害
        var immunity = GetComponent<DamageImmunity>();
        if (immunity != null && immunity.IsImmune) return;

        // 镇痛阻滞：伤害拆分为立即 + 延迟（延迟部分记入池，buff 结束后缓慢扣除）
        var analgesic = GetComponent<AnalgesicBlockRuntime>();
        if (analgesic != null && analgesic.IsActive)
            damage = analgesic.SplitDamage(damage);

        health -= damage;
        health = Mathf.Max(health, 0);

        // 弹出伤害数字（玩家受伤用红色）
        DamagePopup.Spawn(transform.position, damage, isPlayerDamage: true);

        // 角色受击 → 屏幕振动 + 全屏红闪
        if (CameraShake.Instance != null)
        {
            CameraShake.Instance.Shake(1f);
            CameraShake.Instance.FlashRed();
        }

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- Buff 系统属性读写接口 ----------

    /// <summary>通过属性名字符串获取当前值（供 Buff 系统使用）</summary>
    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"      => maxHealth,
            "Health"         => health,
            "MoveSpeed"      => moveSpeed,
            "AttackStrength"  => attackStrength,
            "BulletSpeed"    => bulletSpeed,
            "ShotsPerMinute" => shotsPerMinute,
            "ColliderRadius" => colliderRadius,
            "EvolutionTendency" => evolutionTendency,
            _                => throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'")
        };
    }

    /// <summary>通过属性名字符串设置值，自动触发 OnStatChanged（供 Buff 系统使用）</summary>
    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                maxHealth = Mathf.Max(value, 1f);
                health = Mathf.Min(health, maxHealth);
                break;
            case "Health":
                health = Mathf.Clamp(value, 0f, maxHealth);
                break;
            case "MoveSpeed":
                moveSpeed = Mathf.Max(value, 0f);
                break;
            case "AttackStrength":
                attackStrength = Mathf.Max(value, 0f);
                break;
            case "BulletSpeed":
                bulletSpeed = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinute":
                shotsPerMinute = Mathf.Max(value, 0f);
                break;
            case "ColliderRadius":
                colliderRadius = Mathf.Max(value, 0.01f);
                break;
            case "EvolutionTendency":
                evolutionTendency = Mathf.Clamp(value, -100f, 100f);
                break;
            default:
                throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }

    // ---------- 科技树 / 配置接口 ----------

    /// <summary>应用基础配置值（来自 PlayerConfig SO）</summary>
    public void ApplyBaseStats(PlayerConfig config)
    {
        if (config == null) return;

        maxHealth = config.maxHealth;
        moveSpeed = config.moveSpeed;
        attackStrength = config.attackStrength;
        bulletSpeed = config.bulletSpeed;
        shotsPerMinute = config.shotsPerMinute;
        colliderRadius = config.colliderRadius;
        health = maxHealth; // 重置满血

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    /// <summary>叠加科技树加成（在 ApplyBaseStats 之后调用）</summary>
    public void ApplyBonuses(Dictionary<string, float> bonuses)
    {
        if (bonuses == null || bonuses.Count == 0) return;

        foreach (var kvp in bonuses)
        {
            SetStatValue(kvp.Key, GetStatValue(kvp.Key) + kvp.Value);
        }

        // 加成后恢复满血（生命上限可能增加了）
        if (bonuses.ContainsKey("MaxHealth"))
            health = maxHealth;

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shotsPerMinute = Mathf.Max(shotsPerMinute, 1f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
        evolutionTendency = Mathf.Clamp(evolutionTendency, -100f, 100f);
    }
}

using UnityEngine;

/// <summary>
/// 属性修改 Buff — 修改目标某个属性值。
/// 通过 StatModifier 支持加算/乘算/覆盖叠加。
///
/// 示例: "+30% 攻击力" → statName="AttackStrength", modifier={Multiplicative, 1.3f}
///        "+50 生命值" → statName="MaxHealth", modifier={Additive, 50f}
/// </summary>
[CreateAssetMenu(fileName = "StatBuff", menuName = "Game/Buff Effect/Stat")]
public class StatBuff : BuffEffectBase
{
    [Header("属性修改")]
    [Tooltip("属性名: MaxHealth / MoveSpeed / AttackStrength / BulletSpeed / ShotsPerMinute / ColliderRadius")]
    public string statName;

    [Tooltip("修改器（加算/乘算/覆盖 + 值）")]
    public StatModifier modifier;

    // 记录修改前的值，用于 OnRemove 恢复
    private float _originalValue;

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        var stats = target.GetComponent<PlayerStats>();
        if (stats == null)
        {
            Debug.LogWarning($"StatBuff: target '{target.name}' 没有 PlayerStats 组件");
            return;
        }

        _originalValue = stats.GetStatValue(statName);
        float newValue = StatModifier.Apply(_originalValue, modifier);
        stats.SetStatValue(statName, newValue);
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        var stats = target.GetComponent<PlayerStats>();
        if (stats == null) return;

        stats.SetStatValue(statName, _originalValue);
    }
}

